package com.example.lms.controller;
import com.example.lms.dto.*; import com.example.lms.service.LibrarianService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.net.URI; import java.util.List;
@RestController @RequestMapping("/api/librarians") public class LibrarianController {private final LibrarianService service; public LibrarianController(LibrarianService s){service=s;} @GetMapping public List<LibrarianResponse> list(){return service.list();} @GetMapping("/{id}") public LibrarianResponse get(@PathVariable Long id){return service.get(id);} @PostMapping public ResponseEntity<LibrarianResponse> create(@Valid @RequestBody LibrarianRequest r){var p=service.create(r);return ResponseEntity.created(URI.create("/api/librarians/"+p.id())).body(p);}@PutMapping("/{id}") public LibrarianResponse update(@PathVariable Long id,@Valid @RequestBody LibrarianUpdateRequest r){return service.update(id,r);}@DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable Long id){service.delete(id);}}
